#include <algorithm>
#include <cctype>
#include <iostream>
#include <map>
#include <string>
#include <vector>
int main() {
  std::map<std::string, int> counts;
  std::string word;
  char c;
  auto flush = [&] { if (!word.empty()) { ++counts[word]; word.clear(); } };
  while (std::cin.get(c)) {
    if (std::isalpha(static_cast<unsigned char>(c))) word += static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
    else flush();
  }
  flush();
  std::vector<std::pair<std::string, int>> order(counts.begin(), counts.end());
  std::stable_sort(order.begin(), order.end(), [](const auto& a, const auto& b) { return a.second > b.second; });
  for (std::size_t i = 0; i < order.size() && i < 3; ++i) std::cout << order[i].first << '\t' << order[i].second << '\n';
}

