#include "stats.h"
double stats_mean(const long* values, int count) {
  double sum = 0;
  for (int i = 0; i < count; i++) sum += (double)values[i];
  return count ? sum / count : 0;
}
double stats_variance(const long* values, int count) {
  double mean = stats_mean(values, count), sum = 0;
  for (int i = 0; i < count; i++) sum += ((double)values[i] - mean) * ((double)values[i] - mean);
  return count ? sum / count : 0;
}

