#include <cstdio>
#include <cstdlib>
#include <vector>
int main(int argc, char** argv) {
  const long n = argc > 1 ? std::atol(argv[1]) : 0;
  std::vector<bool> composite(n + 1);
  long count = 0;
  for (long i = 2; i <= n; ++i) {
    if (composite[i]) continue;
    ++count;
    if (i > n / i) continue;  // long is 32 bits on wasm32: i * i would overflow
    for (long j = i * i; j <= n; j += i) composite[j] = true;
  }
  std::printf("%ld\n", count);
}

#include <algorithm>
#include <concepts>
#include <iostream>
#include <ranges>
#include <string>
#include <vector>
struct Entry { std::string name; int score; };
template <std::integral T> T clamp_score(T v) { return std::clamp<T>(v, 0, 100); }
int main() {
  std::vector<Entry> entries;
  for (Entry e; std::cin >> e.name >> e.score;) entries.push_back({e.name, clamp_score(e.score)});
  std::ranges::sort(entries, [](const Entry& a, const Entry& b) { return a.score != b.score ? a.score > b.score : a.name < b.name; });
  for (const auto& [name, score] : entries | std::views::take(2)) std::cout << name << ' ' << score << '\n';
}

