#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static int compare(const void* a, const void* b) { return strcmp(*(const char* const*)a, *(const char* const*)b); }
int main(void) {
  static char buffer[1 << 16];
  char* lines[4096];
  int count = 0;
  size_t used = 0;
  while (count < 4096 && fgets(buffer + used, (int)(sizeof buffer - used), stdin)) {
    char* line = buffer + used;
    size_t length = strlen(line);
    if (length && line[length - 1] == '\n') line[--length] = 0;
    lines[count++] = line;
    used += length + 1;
  }
  qsort(lines, count, sizeof lines[0], compare);
  for (int i = 0; i < count; i++) puts(lines[i]);
  return 0;
}

