#include <stdio.h>
#include <string.h>
#define N 8
#define P 1000000007ULL
static void multiply(unsigned long long r[N][N], unsigned long long a[N][N], unsigned long long b[N][N]) {
  unsigned long long t[N][N];
  for (int i = 0; i < N; i++)
    for (int j = 0; j < N; j++) {
      unsigned long long s = 0;
      for (int k = 0; k < N; k++) s = (s + a[i][k] * b[k][j]) % P;
      t[i][j] = s;
    }
  memcpy(r, t, sizeof t);
}
int main(void) {
  unsigned long long m[N][N], r[N][N];
  for (int i = 0; i < N; i++)
    for (int j = 0; j < N; j++) { m[i][j] = (unsigned long long)(i * N + j + 1); r[i][j] = i == j; }
  for (int e = 1000; e; e >>= 1) {
    if (e & 1) multiply(r, r, m);
    multiply(m, m, m);
  }
  unsigned long long trace = 0;
  for (int i = 0; i < N; i++) trace = (trace + r[i][i]) % P;
  printf("%llu\n", trace);
  return 0;
}

